import { useState } from 'react';
import { JxTagInput, JxChip } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({ defaultTags = [], onChange }: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const handleChange = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const removeTag = (tag: string) => {
    handleChange(tags.filter((t) => t !== tag));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      <JxTagInput
        ariaLabel="Теги статьи"
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={handleChange}
      />
      {tags.length > 0 ? (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
          {tags.map((tag) => (
            <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      ) : (
        <span style={{ color: 'var(--jx-text-2)' }}>Пока нет ни одного тега</span>
      )}
    </div>
  );
}

